from pathlib import Path
from bs4 import BeautifulSoup
import json,re,pymupdf
R=Path(__file__).parent;P=R/'raw';out=[]
def add(country,donor,recipient,year,lo,hi,file,page=None,cash=False):
 out.append({'id':f'think-primary-{len(out)+1}','originName':country,'category':'thinktank','measure':'disclosed-band','amount':None,'amountMin':lo,'amountMax':hi,'year':year,'periodStart':f'{year}-01-01' if recipient=='Atlantic Council' else f'{year-1}-07-01','periodEnd':f'{year}-12-31' if recipient=='Atlantic Council' else f'{year}-06-30','recipient':recipient,'principal':donor,'sourceFile':file,'sourceTitle':f'{recipient} · original donor roll · {year}','locator':f'PDF p. {page}' if page else 'Honor roll; named donor under amount band','page':page,'review':'primary-reviewed','cashVerified':False,'cashReported':cash,'governmentSource':None,'uncertainty':'Recipient disclosure of cash support; band, not an exact audited payment.' if cash else 'Cash, contracts and in-kind contributions; published band, not an exact cash payment.'})
mapping={
 'Embassy of the United Arab Emirates':'United Arab Emirates','Government of the United Kingdom':'United Kingdom','Royal Norwegian Ministry of Foreign Affairs':'Norway','Ministry of Foreign Affairs of Sweden':'Sweden','Royal Norwegian Ministry of Defense':'Norway','Embassy of Bahrain to the United States':'Bahrain','Embassy of Denmark in the United States':'Denmark','German Foreign Federal Office':'Germany','Government of Canada':'Canada','NATO':'NATO','Taipei Economic and Cultural Representative Office (TECRO)':'Taiwan','UN Women':'United Nations','Embassy of Japan to the United States of America':'Japan','Japan External Trade Organization':'Japan','The Korea Foundation':'South Korea','Republic of Lithuania':'Lithuania','Swiss Government Foreign Affairs':'Switzerland','United Nations Children’s Fund (UNICEF)':'United Nations','Australia Office of National Intelligence':'Australia','Embassy of the Republic of Estonia to the United States':'Estonia','The Ministry of Defence of the Netherlands':'Netherlands','Ministry of Defence of the Republic of Singapore':'Singapore','Ministry of Foreign Affairs of the Czech Republic':'Czechia','Poland Ministry of Foreign Affairs':'Poland','Swedish Energy Agency':'Sweden','The World Bank':'World Bank','United Nations':'United Nations','Embassy of Spain the United States':'Spain','Mexican Chamber of Deputies':'Mexico'}
file='think-primary-atlantic-2024.html';s=BeautifulSoup((P/file).read_bytes(),'html.parser');lines=s.select_one('article').get_text('\n',strip=True).splitlines();lo=hi=None
for line in lines:
 if line.startswith('$') and 'Contributors' in line:
  nums=re.findall(r'[\d,]+',line);lo=int(nums[0].replace(',',''));hi=int(nums[1].replace(',','')) if len(nums)>1 else None
 if line in mapping:add(mapping[line],line,'Atlantic Council',2024,lo,hi,file,cash=True)
manual2019=[
 ('United Kingdom','British Foreign and Commonwealth Office',1000000,None,52),('United Arab Emirates','Embassy of the United Arab Emirates',1000000,None,52),('Sweden','Swedish Ministry for Foreign Affairs',250000,499999,52),('Bahrain','Embassy of Bahrain to the United States',100000,249999,52),('Japan','Embassy of Japan to the United States',100000,249999,52),('South Korea','The Korea Foundation',100000,249999,52),('Finland','Ministry of Defense of Finland',100000,249999,52),('Lithuania','Ministry of National Defense of Lithuania',100000,249999,52),('NATO','NATO Public Diplomacy Division',100000,249999,52),('NATO','NATO StratCom Center of Excellence',100000,249999,52),('Norway','Royal Norwegian Ministry of Defense',100000,249999,52),('Norway','Royal Norwegian Ministry of Foreign Affairs',100000,249999,52),('Taiwan','Taiwan Economic and Cultural Representative Office (TECRO)',100000,249999,52),('Germany','Federal Foreign Office of Germany',50000,99999,52),('United Kingdom','Her Majesty’s Government',50000,99999,52),('Netherlands','Ministry of Foreign Affairs of the Netherlands',50000,99999,52),('Canada','Canadian Department of Foreign Affairs Trade & Development',10000,24999,52),('Lithuania','Embassy of Lithuania to the United States',10000,24999,53),('Slovakia','Embassy of the Slovak Republic',10000,24999,53),('Switzerland','Federal Department of Foreign Affairs for Switzerland',10000,24999,53),('Japan','JETRO',10000,24999,53),('France','Ministry of Defense of the French Republic',10000,24999,53),('European Union','Delegation of the European Union to the United States',5000,9999,53),('European Union','European Union Institute for Security Studies',5000,9999,53),('Luxembourg','Luxembourg Ministry of Foreign Affairs',5000,9999,53),('Lithuania','Ministry of Energy of the Republic of Lithuania',5000,9999,53),('United Kingdom','The British Embassy in Washington, DC',1000,4999,53)]
for country,donor,lo,hi,page in manual2019:add(country,donor,'Atlantic Council',2019,lo,hi,'think-primary-atlantic-2019.pdf',page,True)
brook2025=[('Sweden','Ministry for Foreign Affairs, Sweden',500000,999999,1),('Japan','Japan International Cooperation Agency (JICA)',250000,499999,2),('South Korea','Korea Development Institute',250000,499999,2),('Norway','Norwegian Ministry of Foreign Affairs',250000,499999,2),('Taiwan','Taipei Economic and Cultural Representative Office in the United States',250000,499999,2),('United Kingdom','UK Department for Business, Energy & Industrial Strategy',250000,499999,2),('South Korea','The Korea Foundation',100000,249999,3),('Denmark','Embassy of Denmark in the United States',50000,99999,4),('France','Embassy of France to the United States',50000,99999,4),('Japan','Japan Air Self Defense Force',25000,49999,5),('United Nations','United Nations Development Programme',10000,24999,6),('World Bank','The World Bank Group',10000,24999,7)]
for country,donor,lo,hi,page in brook2025:add(country,donor,'Brookings Institution',2025,lo,hi,'think-primary-Brookings-Intitution-Honor-Roll-2025-Fiscal-Year.pdf',page)
add('Qatar','Embassy of the State of Qatar','Brookings Institution',2021,2000000,None,'think-primary-2021-annual-report.pdf',44)
add('Sweden','Swedish Ministry for Foreign Affairs','Brookings Institution',2021,500000,999999,'think-primary-2021-annual-report.pdf',44)
add('Australia','Australian Government, Department of Foreign Affairs & Trade','Brookings Institution',2021,250000,499999,'think-primary-2021-annual-report.pdf',44)
# Verify every curated name against its source text (typography-insensitive).
def canon(x):return re.sub(r'[^a-z0-9]','',x.lower())
for r in out:
 p=P/r['sourceFile']
 if p.suffix=='.pdf':
  doc=pymupdf.open(p);pg=r['page']-1;txt=doc[pg].get_text()+(doc[pg+1].get_text() if pg+1<len(doc) else '')
 else:txt=BeautifulSoup(p.read_bytes(),'html.parser').get_text(' ',strip=True)
 assert canon(r['principal']) in canon(txt) or (r['principal'].startswith('Canadian Department') and 'canadiandepartment' in canon(txt) and 'offoreignaffairstradedevelopment' in canon(txt)),(r['principal'],r['sourceFile'])
(R/'parsed'/'think-primary.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
print('Reviewed primary bands',len(out),'origins',len({r['originName'] for r in out}))
